use std::cmp::Ordering;
use std::fmt::{self, Display};
use std::vec::Vec;

#[derive(Debug, Clone)]
struct Contact {
    first_name: String,
    last_name: String,
    phone_number: String,
}

impl Contact {
    fn new(first_name: &str, last_name: &str, phone_number: &str) -> Self {
        Contact {
            first_name: first_name.to_string(),
            last_name: last_name.to_string(),
            phone_number: phone_number.to_string(),
        }
    }
}

// Implement Display to customize the output format of Contact
impl Display for Contact {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "{}, {}: {}",
            self.last_name, self.first_name, self.phone_number
        )
    }
}

// Comparison functions for sorting by first name, last name, and phone number
fn compare_by_first_name(a: &Contact, b: &Contact) -> Ordering {
    a.first_name.cmp(&b.first_name)
}

fn compare_by_last_name(a: &Contact, b: &Contact) -> Ordering {
    a.last_name.cmp(&b.last_name)
}

fn compare_by_phone_number(a: &Contact, b: &Contact) -> Ordering {
    a.phone_number.cmp(&b.phone_number)
}

// Function to print a vector of contacts
fn print_contacts(contacts: &[Contact]) {
    for contact in contacts {
        println!("{}", contact);
    }
}

fn main() {
    let mut demo_contacts: Vec<Contact> = vec![
        Contact::new("Javon", "Bernard", "555-667-2345"),
        Contact::new("Kiana", "Lester", "234-745-4534"),
        Contact::new("Lia", "Baldwin", "546-234-7578"),
        Contact::new("Ryleigh", "Liu", "094-242-7745"),
        Contact::new("Shea", "Gibbs", "251-647-8941"),
        Contact::new("Sabrina", "Galvan", "345-798-3168"),
        Contact::new("Glenn", "Henry", "654-984-8664"),
        Contact::new("Lucia", "Wright", "134-798-6464"),
        Contact::new("Annika", "Carr", "461-641-7497"),
        Contact::new("Bruno", "Frank", "465-065-4610"),
    ];

    // Sort by first name
    println!("Sort by first name...");
    demo_contacts.sort_by(compare_by_first_name);
    print_contacts(&demo_contacts);
    println!();

    // Sort by last name
    println!("Sort by last name...");
    demo_contacts.sort_by(compare_by_last_name);
    print_contacts(&demo_contacts);
    println!();

    // Sort by phone number
    println!("Sort by phone number...");
    demo_contacts.sort_by(compare_by_phone_number);
    print_contacts(&demo_contacts);
