const N: usize = 4;

// Function to swap the first and last row of a matrix
fn interchange_first_last(matrix: &mut [[i32; N]; N]) {
    let rows = N;

    // Swapping the elements between the first and last rows
    for i in 0..N {
        let temp = matrix[0][i];
        matrix[0][i] = matrix[rows - 1][i];
        matrix[rows - 1][i] = temp;
    }
}

fn main() {
    // Initialize the matrix
    let mut matrix: [[i32; N]; N] = [
        [8, 9, 7, 6],
        [4, 7, 6, 5],
        [3, 2, 1, 8],
        [9, 9, 7, 7],
    ];

    // Call the function to interchange the first and last rows
    interchange_first_last(&mut matrix);

    // Printing the interchanged matrix
    for row in matrix.iter() {
        for &elem in row.iter() {
            print!("{} ", elem);
        }
        println!();
    }
}
