class Integer {
private:
    int i;

public:
    // Parameterised constructor
    Integer(int i = 0)
    {
        this->i = i;
    }

    // Overloading the prefix operator
    Integer& operator++()
    {
        ++i;
        // returned value should be a reference to *this
        return *this;
    }

    // Function to display the value of i
    void display()
    {
        cout << "i = " << i << endl;
    }
};

