use std::f64;

// Function to compute the determinant of a matrix recursively
fn determinant(matrix: &[[i32; 4]; 4], n: usize) -> i32 {
    let mut det = 0;

    // Base case for 1x1 matrix
    if n == 1 {
        return matrix[0][0];
    }

    // Base case for 2x2 matrix
    if n == 2 {
        return matrix[0][0] * matrix[1][1] - matrix[1][0] * matrix[0][1];
    }

    // Recursive case for larger matrices
    for x in 0..n {
        let mut submatrix: [[i32; 4]; 4] = [[0; 4]; 4];
        let mut subi = 0;

        for i in 1..n {
            let mut subj = 0;
            for j in 0..n {
                if j == x {
                    continue;
                }
                submatrix[subi][subj] = matrix[i][j];
                subj += 1;
            }
            subi += 1;
        }

        let sign = if x % 2 == 0 { 1 } else { -1 };
        det += sign * matrix[0][x] * determinant(&submatrix, n - 1);
    }

    det
}

