fn count_triplets(arr: &[i32]) -> usize {
    let unique_values: HashSet<i32> = arr.iter().cloned().collect();
    let mut count = 0;
    let n = arr.len();

    for i in 0..n - 1 {
        for j in i + 1..n {
            let xr = arr[i] ^ arr[j];
            if unique_values.contains(&xr) && xr != arr[i] && xr != arr[j] {
                count += 1;
            }
        }
    }
    count / 3
}

