// Function to add two binary strings and return the result as a third string
fn add_binary(a: &str, b: &str) -> String {
    let mut i = a.len() as isize - 1; // Start from the end of string a
    let mut j = b.len() as isize - 1; // Start from the end of string b
    let mut carry = 0;  // Initialize carry
    let mut result = String::new();

    // Loop until we reach the start of both strings or there is no carry
    while i >= 0 || j >= 0 || carry != 0 {
        let bit_a = if i >= 0 { a.chars().nth(i as usize).unwrap().to_digit(2).unwrap() } else { 0 };
        let bit_b = if j >= 0 { b.chars().nth(j as usize).unwrap().to_digit(2).unwrap() } else { 0 };

        let sum = bit_a + bit_b + carry;
        carry = sum / 2;
        result.push(char::from_digit(sum % 2, 2).unwrap());

        // Move to the previous bit
        if i >= 0 { i -= 1; }
        if j >= 0 { j -= 1; }
    }

    // Reverse the result as we were adding from the least significant bit
    result.chars().rev().collect()
}

fn main() {
    let a = "1101";
    let b = "100";
    // Call the add_binary function and print the result
    println!("{}", add_binary(a, b)); // Should print 10001
}
```

