use std::fmt::Debug;

// Define a struct for Stack with a generic type T
const SIZE: usize = 5; // Defining stack size as constant

struct Stack<T> {
    top: i32,
    st: [Option<T>; SIZE],
}

impl<T: Debug> Stack<T> { // Add the Debug trait bound here
    // Constructor for the Stack struct
    fn new() -> Self {
        Stack {
            top: -1,
            st: [None, None, None, None, None], // Initialize with None, representing an empty stack
        }
    }

    // Method to push an element onto the stack
    fn push(&mut self, k: T) {
        if self.is_full() {
            println!("Stack is full");
            return;
        }
        self.top += 1;
        self.st[self.top as usize] = Some(k);
        println!("Inserted element {:?}", self.st[self.top as usize]);
    }

    // Method to check if the stack is empty
    fn is_empty(&self) -> bool {
        self.top == -1
    }

    // Method to check if the stack is full
    fn is_full(&self) -> bool {
        self.top == (SIZE as i32 - 1)
    }

    // Method to pop an element from the stack
    fn pop(&mut self) -> Option<T> {
        if self.is_empty() {
            println!("Stack is empty");
            return None;
        }
        let popped_element = self.st[self.top as usize].take(); // Take the element out
        self.top -= 1;
        popped_element
    }

    // Method to get the top element of the stack
    fn top_element(&self) -> Option<&T> {
        if self.is_empty() {
            println!("Stack is empty");
            return None;
        }
        self.st[self.top as usize].as_ref()
    }
}

fn main() {
    // Creating instances of Stack for integer and string types
    let mut integer_stack = Stack::<i32>::new();
    let mut string_stack = Stack::<String>::new();

    // Adding elements to the integer stack
    integer_stack.push(2);
    integer_stack.push(54);
    integer_stack.push(255);

    // Adding elements to the string stack
    string_stack.push("Welcome".to_string());
    string_stack.push("to".to_string());
    string_stack.push("GeeksforGeeks".to_string());

    // Removing an element from the integer stack
    if let Some(popped) = integer_stack.pop() {
        println!("{} is removed from stack", popped);
    }

    // Removing the top element from the string stack
    if let Some(popped) = string_stack.pop() {
        println!("{} is removed from stack", popped);
    }

    // Print the top element in the integer stack
    if let Some(top) = integer_stack.top_element() {
        println!("Top element is {:?}", top);
    }

    // Print the top element in the string stack
    if let Some(top) = string_stack.top_element() {
        println!("Top element is {:?}", top);
    }
}

