fn rotate_array(mut nums: Vec<i32>, k: usize) -> Vec<i32> {
    let n = nums.len();
    let k = k % n; // Handle cases where k is larger than the length of the array
    if k == 0 {
        return nums; // If k is 0, no rotation needed
    }

    // Calculate the number of cycles based on the GCD of 'n' and 'k'
    let cycles = gcd(n as i32, k as i32) as usize;

    // Perform rotation for each cycle
    for i in 0..cycles {
        let mut start = i; // Start index of the current cycle
        let mut current = start; // Current index being processed
        let mut prev = nums[start]; // Store the value to be replaced

        loop {
            // Calculate the next index after rotation
            let next_idx = (current + k) % n;
            // Swap the values and update 'prev' with the replaced value
            let temp = nums[next_idx];
            nums[next_idx] = prev;
            prev = temp;
            // Update 'current' to the next index
            current = next_idx;
            // Break if the cycle completes (back to the start index)
            if current == start {
                break;
            }
        }
    }

    nums // Return the rotated array
