fn draw_triangle(tsize: usize, order: char) -> Result<(), String> {
    if tsize < 2 || tsize > 20 {
        return Err("Error: Size must be between 2 and 20".to_string());
    }

    println!(); // Add an extra newline at the top for spacing

    match order {
        'r' => {
            for i in 1..=tsize {
                println!(" {}", "&".repeat(i));
            }
            for i in (1..tsize).rev() {
                println!(" {}", "&".repeat(i));
            }
        }
        'd' => {
            let mut space = 0;
            let mut tester = tsize;
            for _ in 0..tsize {
                let spaces = " ".repeat(space + 1);
                let symbols = "&".repeat(tester * 2 - 1);
                println!("{}{}", spaces, symbols);
                space += 1;
                tester -= 1;
            }
        }
        'u' => {
            let mut tester = tsize;
            for i in 0..tsize {
                let spaces = " ".repeat(tester);
                let symbols = "&".repeat(i * 2 + 1);
                println!("{}{}", spaces, symbols);
                tester -= 1;
            }
        }
        'l' => {
            let mut tester = tsize;
            for i in 1..=tsize {
                let spaces = " ".repeat(tester);
                let symbols = "&".repeat(i);
                println!("{}{}", spaces, symbols);
                tester -= 1;
            }
            tester = tsize;
            let mut space = 0;
            for _ in 1..tsize {
                let spaces = " ".repeat(space + 2);
                let symbols = "&".repeat(tester - 2);
                println!("{}{}", spaces, symbols);
                tester -= 1;
                space += 1;
            }
        }
        _ => {
            return Err("Error: Enter 'r', 'd', 'u', or 'l' only".to_string());
        }
    }

    println!(); // Add an extra newline at the bottom for spacing
    Ok(())
