use rand::Rng;
use std::io::{self, Write};

struct Player {
    name: String,
    total_money: i32,
}

struct WagerResult {
    did_win: bool,
    money_change_amount: i32,
    wager: i32,
    guess: i32,
}

impl std::fmt::Display for WagerResult {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "You bet {} and guessed {}", self.wager, self.guess)?;
        write!(f, "\nYou ")?;
        if self.did_win {
            write!(f, "won ")?;
        } else {
            write!(f, "lost ")?;
        }
        write!(f, "{}", self.money_change_amount.abs())?;
        Ok(())
    }
}

struct NumberGenerator {
    min: i32,
    max: i32,
}

impl NumberGenerator {
    fn new(min: i32, max: i32) -> Self {
        NumberGenerator { min, max }
    }

    fn generate_random_number(&self) -> i32 {
        let mut rng = rand::thread_rng();
        rng.gen_range(self.min..=self.max)
    }
}

struct Game {
    player: Player,
    number_generator: NumberGenerator,
}

impl Game {
    fn new(player: Player) -> Self {
        Game {
            player,
            number_generator: NumberGenerator::new(1, 10),
        }
    }

    fn start_game(&mut self) {
        print!("Enter your name: ");
        io::stdout().flush().unwrap();
        let mut name = String::new();
        io::stdin().read_line(&mut name).unwrap();
        self.player.name = name.trim().to_string();

        print!("Enter start money amount: ");
        io::stdout().flush().unwrap();
        let mut money = String::new();
        io::stdin().read_line(&mut money).unwrap();
        self.player.total_money = money.trim().parse().unwrap();
    }

    fn keep_playing(&self) -> bool {
        print!("Play again? (Y/N): ");
        io::stdout().flush().unwrap();
        let mut response = String::new();
        io::stdin().read_line(&mut response).unwrap();
        response.trim().eq_ignore_ascii_case("y")
    }

    fn get_bet_amount(&self) -> i32 {
        print!(
            "Enter bet amount (1 - {}): ",
            self.player.total_money
        );
        io::stdout().flush().unwrap();
        let mut wager = String::new();
        io::stdin().read_line(&mut wager).unwrap();
        wager.trim().parse().unwrap()
    }

    fn get_guess(&self) -> i32 {
        print!("Enter guess (1-10): ");
        io::stdout().flush().unwrap();
        let mut guess = String::new();
        io::stdin().read_line(&mut guess).unwrap();
        guess.trim().parse().unwrap()
    }

    fn play_round(&mut self) -> WagerResult {
        let wager = self.get_bet_amount();
        let guess = self.get_guess();

        let number = self.number_generator.generate_random_number();

        let mut result = WagerResult {
            did_win: false,
            money_change_amount: 0,
            wager,
            guess,
        };

        if number == guess {
            result.did_win = true;
            result.money_change_amount = wager * 10;
        } else {
            result.did_win = false;
            result.money_change_amount = -wager;
        }

        self.player.total_money += result.money_change_amount;
        result
    }

    fn game_over(&self) -> bool {
        self.player.total_money <= 0
    }
}

fn main() {
    println!("----- Casino! -----");

    let player = Player {
        name: String::new(),
        total_money: 0,
    };

    let mut game = Game::new(player);
    game.start_game();

    while !game.game_over() {
        let result = game.play_round();
        println!("{}", result);

        if game.game_over() {
            println!("You lost, game over");
            break;
        }

        if !game.keep_playing() {
            break;
        }
    }

    println!("Game over! Thanks for playing!");
}
