bool is_happy_number(int num) {
    int slow = num, fast = num;
    auto get_next = [](int n) {
        int sum = 0;
        while (n > 0) {
            int digit = n % 10;
            sum += digit * digit;
            n /= 10;
        }
        return sum;
    };
    do {
        slow = get_next(slow);
        fast = get_next(get_next(fast));
    } while (slow != fast);

