    }
    sum
}

fn is_happy_number(mut num: i32) -> bool {
    let mut slow = num;
    let mut fast = num;

    loop {
        slow = get_next(slow);
        fast = get_next(get_next(fast));

        if slow == fast {
            break;
        }
    }

