    if den == 0.0 {
        Err(String::from("Math error: Attempted to divide by zero"))
    } else {
        Ok(den)
    }
}

fn division(num: f32, den: f32) -> Result<f32, String> {
    match check_denominator(den) {
        Ok(valid_den) => Ok(num / valid_den),
        Err(e) => Err(e),
    }
}

