// Rust program with optimized implementation of Bubble Sort

fn bubble_sort(arr: &mut Vec<i32>) {
    let n = arr.len();
    for i in 0..n - 1 {
        let mut swapped = false;

        for j in 0..n - i - 1 {
            if arr[j] > arr[j + 1] {
                // Directly swap elements in place
                arr.swap(j, j + 1);
                swapped = true;
            }
        }

        // If no elements were swapped, break early to optimize
        if !swapped {
            break;
