use std::thread;
use std::time::Duration;

// Simulate a long computation
fn long_computation(x: i32, duration_seconds: u64, identifier: char) -> i32 {
    for _ in 0..(duration_seconds * 10) {
        thread::sleep(Duration::from_millis(100));
        print!("{}", identifier);
        io::stdout().flush().unwrap(); // Ensure immediate output
    }
    42 + x
}

fn main() {
    let mut x = 5;
    let y = 6;

    println!("main thread   : x = {}, y = {}", x, y);
    println!("main thread   : launching lambda thread");

    // Spawn a new thread to perform the long computation
    let lambda_thread = thread::spawn({
        let x = x; // Capture `x` by value for the lambda thread
        move || {
            println!("lambda thread : x = {}", x);
            let answer = long_computation(x, 6, 'l');
            println!("\nlambda thread : long computation completed");
            println!("lambda thread : x = {}", x);
            answer
        }
    });

    // Update `x` in the main thread and perform its own long computation
    x = 0;
    println!("main thread   : x = {}, y = {}", x, y);
    let main_thread_result = long_computation(x, 3, 'm');
    println!("\nmain thread   : long computation completed");

    // Wait for the lambda thread to finish and get the result
    match lambda_thread.join() {
        Ok(lambda_thread_result) => {
            println!("main thread   : result = {}", main_thread_result);
            println!("lambda thread : result = {}", lambda_thread_result);
        }
        Err(e) => {
            eprintln!("Error joining lambda thread: {:?}", e);
        }
    }
}
