        println!("                   4. Exit Application");
        println!("--------------------------------------------------------------------------");

        let choice = get_input("Enter your choice: ");
        match choice {
            1 => calculate_gpa(),
            2 => calculate_cgpa(),
            3 => method(),
            4 => break, // Exit the application
            _ => println!("You have entered wrong input. Try again!"),
        }
    }
}

fn clear_screen() {
    // Clears the screen for a cleaner interface
    print!("{esc}[2J{esc}[1;1H", esc = 27 as char);
    io::stdout().flush().unwrap();
}

fn get_input(prompt: &str) -> i32 {
    let mut input = String::new();
    println!("{}", prompt);
    io::stdout().flush().unwrap();
    io::stdin().read_line(&mut input).unwrap();
    input.trim().parse().unwrap_or(0)
}

fn calculate_gpa() {
    clear_screen();
    println!("-------------- GPA Calculating -----------------");

    let num_subjects = get_input("How many subject's points do you want to calculate? : ");
    
    let mut credits = Vec::with_capacity(num_subjects as usize);
    let mut points = Vec::with_capacity(num_subjects as usize);

    for i in 0..num_subjects {
        let credit = get_input(&format!("Enter the credit for subject {}: ", i + 1));
        let point = get_input(&format!("Enter the point for subject {}: ", i + 1));
        credits.push(credit as f32);
        points.push(point as f32);
        println!("-----------------------------------\n");
    }

    let total_points: f32 = credits.iter().zip(&points)
        .map(|(credit, point)| credit * point)
        .sum();
