use tempfile::NamedTempFile;

fn main() -> io::Result<()> {
    // Create a temporary file
    let mut temp_file = NamedTempFile::new().map_err(|e| {
        eprintln!("Error creating temporary file: {}", e);
        e
    })?;

    // Content to be written in the temporary file
    let content = "Hello World!";

    // Write content to the temporary file
    temp_file.write_all(content.as_bytes())?;

    // Seek back to the beginning before reading
    temp_file.as_file_mut().seek(SeekFrom::Start(0))?;

    // Read the content from the temporary file
    let mut buffer = String::new();
    temp_file.as_file_mut().read_to_string(&mut buffer)?;

    // Print the content
    println!("{}", buffer);

    // The file will be automatically deleted when `temp_file` goes out of scope
    Ok(())
}
