use std::collections::HashMap;

struct FactorialHelper {
    cache: HashMap<i32, i64>,
}

impl FactorialHelper {
    fn new() -> Self {
        FactorialHelper {
            cache: HashMap::new(),
        }
    }

    fn factorial(&mut self, n: i32) -> i64 {
        if let Some(&result) = self.cache.get(&n) {
            return result;
        }

        let mut result = 1;
        for i in 1..=n {
            result *= i as i64;
        }

        self.cache.insert(n, result);
        result
    }
}

fn main() {
    let mut factorial = FactorialHelper::new();
    println!("{}", factorial.factorial(5));
}
```

