// C++ Program to find Nth
// Armstrong Number
#include <bits/stdc++.h>
#include <math.h>
using namespace std;

// Function to find Nth
// Armstrong Number
int NthArmstrong(int n)
{
        int count = 0;

        // Upper limit from integer
        for (int i = 1; i <= INT_MAX; i++) {
                int num = i, rem, digit = 0, sum = 0;

                // Copy the value for num in num
                num = i;

                // Find total digits in num
                digit = (int)log10(num) + 1;

                // Calculate sum of power of digits
                while (num > 0) {
                        rem = num % 10;
                        sum = sum + pow(rem, digit);
                        num = num / 10;
                }
                // Check for Armstrong number
                if (i == sum)
                        count++;
                if (count == n)
                        return i;
        }
}

// Driver code
int main()
{
        int n = 12;
        cout << NthArmstrong(n);
        return 0;
}
```

rust_code:
```
fn nth_armstrong(n: usize) -> Option<u32> {
    let mut count = 0;

    for i in 1..u32::MAX {
        let mut num = i;
        let digit = (num as f64).log10() as u32 + 1;
        let mut sum = 0;

        while num > 0 {
            let rem = num % 10;
            sum += rem.pow(digit);
            num /= 10;
        }

        if i == sum {
            count += 1;
        }

        if count == n {
            return Some(i);
        }
    }
    None
}

fn main() {
    let n = 12;
    if let Some(result) = nth_armstrong(n) {
        println!("{}", result);
    } else {
        println!("No such Armstrong number found.");
    }
}
```

