class Complex 
{ 
    // Declaring variables
    public: int real, imaginary;

    // Constructor to accept
    // real and imaginary part
    Complex(int tempReal = 0, 
            int tempImaginary = 0)
    {
        real = tempReal;
        imaginary = tempImaginary;
    }

    // Defining addComp() method
    // for adding two complex number
