// Rust Program to Add Two Complex Numbers

// Define the Complex struct with fields real and imaginary
#[derive(Debug)]
struct Complex {
    real: i32,
    imaginary: i32,
}

impl Complex {
    // Constructor to initialize Complex number
    fn new(real: i32, imaginary: i32) -> Self {
        Complex { real, imaginary }
    }

    // Method to add two Complex numbers
    fn add(&self, other: &Complex) -> Complex {
        Complex {
            real: self.real + other.real,
            imaginary: self.imaginary + other.imaginary,
        }
    }
}

fn main() {
    // First Complex number
    let c1 = Complex::new(3, 2);
    // Second Complex number
    let c2 = Complex::new(9, 5);

    // Print first complex number
    println!("Complex number 1: {} + i{}", c1.real, c1.imaginary);

    // Print second complex number
    println!("Complex number 2: {} + i{}", c2.real, c2.imaginary);

    // Add two complex numbers using add() method
    let c3 = c1.add(&c2);

    // Print the sum of the two complex numbers
    println!("Sum of complex numbers: {} + i{}", c3.real, c3.imaginary);
}
