use std::fmt;

// A function that returns the index of the day of the date - day/month/year
// 0 -> Sunday, 1 -> Monday, ..., 6 -> Saturday
fn day_number(day: u32, month: u32, year: u32) -> u32 {
    let t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
    let mut year = year;
    if month < 3 {
        year -= 1;
    }
    (year + year / 4 - year / 100 + year / 400 + t[(month - 1) as usize] + day) % 7
}

// A function to get the month name for a given month number
fn get_month_name(month_number: u32) -> &'static str {
    let months = [
        "January", "February", "March", "April", "May", "June", "July", "August",
        "September", "October", "November", "December",
    ];
    months[month_number as usize]
}

// A function to return the number of days in a month
fn number_of_days(month_number: u32, year: u32) -> u32 {
    match month_number {
        0 | 2 | 4 | 6 | 7 | 9 | 11 => 31, // Months with 31 days
        3 | 5 | 8 | 10 => 30,             // Months with 30 days
        1 => {
            if (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0) {
                29 // Leap year February
            } else {
                28 // Non-leap year February
            }
        }
        _ => 0, // Invalid month (shouldn't happen)
    }
}

// A function to print the calendar for the given year
fn print_calendar(year: u32) {
    println!("         Calendar - {}\n", year);

    // Determine the starting day of the year
    let mut current = day_number(1, 1, year);

    // Loop through all months
    for month in 0..12 {
        let days = number_of_days(month, year);

        // Print the current month name
        println!("\n  ------------{}-------------", get_month_name(month));

        // Print the column headers
        println!("  Sun  Mon  Tue  Wed  Thu  Fri  Sat");

        // Print leading spaces for the first week
        for _ in 0..current {
            print!("     ");
        }

        // Print the days of the month
        let mut k = current;
        for day in 1..=days {
            print!("{:5}", day);

            if k == 6 {
                k = 0;
                println!();
            } else {
                k += 1;
            }
        }

        if k != 0 {
            println!();
        }

        // Set the starting day of the next month
        current = k;
    }
}

fn main() {
    let year = 2016;
    print_calendar(year);
}
